SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции2003.YEAR, Станции2003.NUST, Станции2003.E, Станции2003.EOTP, Станции2003.EURT, Станции2003.EUST, Станции2003.Q, Станции2003.TURT, Станции2003.TUST, Станции2003.B, Станции2003.GAZ, Доп_угли2003.gazpp, Станции2003.MAZUT, Станции2003.TORF, Станции2003.SLAN, Станции2003.GTT, Станции2003.PROCH, Станции2003.UGOL, Станции2003.DON, Станции2003.PODM, Станции2003.PECH, Доп_угли2003.int, Доп_угли2003.vork, Станции2003.ARKT, Станции2003.KUZN, Станции2003.URAL, Доп_угли2003.sver, Доп_угли2003.chel, Доп_угли2003.kizel, Станции2003.BASHK, Станции2003.EKIB, Станции2003.KARAG, Станции2003.KAN, Доп_угли2003.nazar, Доп_угли2003.ibor, Доп_угли2003.berez, Доп_угли2003.per, Станции2003.IRKUT, Доп_угли2003.azey, Доп_угли2003.cher, Доп_угли2003.jer, Станции2003.HAK, Станции2003.TUV, Станции2003.BUR, Доп_угли2003.gusin, Доп_угли2003.tugn, Станции2003.CHIT, Доп_угли2003.har, Доп_угли2003.urt, Станции2003.[YAKUT] AS Выражение1, Станции2003.[AMUR] AS Выражение2, Станции2003.URG, Станции2003.PRIM, Станции2003.LUCH, Станции2003.MAG, Станции2003.SAH, Станции2003.USHUM, Станции2003.QOTR, Станции2003.SNK, Станции2003.EWTP, Станции2003.NT, Станции2003.OBOR, Станции2003.VED, Станции2003.OBL, Станции2003.DEP, Станции2003.OES, Станции2003.ER, Станции2003.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO
FROM (((Станции2003 INNER JOIN Имена_станций ON Станции2003.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции2003.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции2003.OBL=Имена_областей.OBL) LEFT JOIN Доп_угли2003 ON (Станции2003.NUMB1120=Доп_угли2003.NUMB1120) AND (Станции2003.YEAR=Доп_угли2003.YEAR);
